mkdir -p src && cat > src/limiter.py <<'EOF'
import time

class RateLimiter:
    def __init__(self, max_requests=3):
        self.max_requests = max_requests
        self.clients = {}

    def check(self, ip):
        now = time.time()
        if ip not in self.clients:
            self.clients[ip] = (now, 1)
            return True
        start, count = self.clients[ip]
        if now - start > 60:
            self.clients[ip] = (now, 1)
            return True
        if count < self.max_requests:
            self.clients[ip] = (start, count + 1)
            return True
        return False
EOF
